PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?husband ?husbandName ?birthPlace WHERE {
  dbr:Emmanuelle_Seigner dbp:spouse ?husband .
  OPTIONAL { ?husband rdfs:label ?husbandName FILTER (lang(?husbandName) = "en") }
  OPTIONAL { ?husband dbp:birthPlace ?bp1 . }
  OPTIONAL { ?husband dbo:birthPlace ?bp2 . }
  BIND (COALESCE(?bp1, ?bp2) AS ?birthPlace)
}
LIMIT 100

